-- Multi-object transaction: both writes must succeed or neither does
BEGIN;
  UPDATE accounts SET balance = balance - 100 WHERE id = 'alice';
  UPDATE accounts SET balance = balance + 100 WHERE id = 'bob';
COMMIT;

-- Without a transaction, a crash between the two UPDATEs
-- would debit Alice but never credit Bob

-- Explicit locking: SELECT FOR UPDATE prevents concurrent reads until commit
BEGIN;
  SELECT balance FROM accounts WHERE id = 'alice' FOR UPDATE;
  -- no other transaction can read this row with FOR UPDATE until we commit
  UPDATE accounts SET balance = balance - 100 WHERE id = 'alice';
COMMIT;

-- Alice's transaction:
BEGIN;
  -- Check: are there at least 2 doctors on call?
  SELECT COUNT(*) FROM on_call WHERE on_duty = true;
  -- Returns 2. Safe to proceed.
  UPDATE on_call SET on_duty = false WHERE doctor = 'alice';
COMMIT;

-- Bob's transaction (concurrent with Alice's):
BEGIN;
  SELECT COUNT(*) FROM on_call WHERE on_duty = true;
  -- Also returns 2 (both see the same snapshot — Alice's write hasn't committed)
  UPDATE on_call SET on_duty = false WHERE doctor = 'bob';
COMMIT;

-- Result: 0 doctors on call. Invariant violated.

-- Materialising conflict: lock the pre-created slot row
BEGIN;
  -- Lock the time-slot row to prevent phantom booking
  SELECT * FROM room_slots
  WHERE room = 'Narnia' AND slot_time = '2026-06-01 14:00'
  FOR UPDATE;

  -- Now safe: any concurrent transaction trying to book this slot
  -- will block on the FOR UPDATE above
  INSERT INTO bookings (room, slot_time, user_id)
  VALUES ('Narnia', '2026-06-01 14:00', 'alice');
COMMIT;
